for b in pb: b.rotation_quaternion = Quaternion(); b.location = V()

# ---------------------------------------------------------------- stride measurement (left foot's ground contact travel)
def measure_slide(action):
    # measure: with the root moving at SPEED, how far does each planted contact point (heel, then flat, then ball) move?
    sc = bpy.context.scene; sc.render.fps = FPS
    rig.animation_data.action = bpy.data.actions[action]
    slide = 0.0
    for side, off in (("Left", 0.0), ("Right", 0.5)):
        fb = pb[f"{side}Foot"]; inv = fb.bone.matrix_local.inverted()
        lx = LEGS[side]["ankx"]
        base = {}
        for f in range(WALK_N - 1):
            lp = (f / (WALK_N - 1) + off) % 1.0
            if lp >= DUTY * 0.98:
                continue
            sc.frame_set(f + 1)
            m = rig.matrix_world @ fb.matrix
            heelp = m @ (inv @ V((lx, LEGS[side]["heel"], 0.0)))
            ballp = m @ (inv @ V((lx, LEGS[side]["ball"], 0.0)))
            u = lp / DUTY
            phase = 0 if u < HEEL_PH else (1 if u < TOE_PH else 2)
            pt = heelp if phase == 0 else (ballp if phase == 2 else (heelp + ballp) / 2)
            y = pt.y + SPEED * (lp * CYCLE)             # world y once the root moves forward
            key_ = (phase,)
            base.setdefault(key_, y)
            slide = max(slide, abs(y - base[key_]))
    return slide
slide = measure_slide("walk")

# ---------------------------------------------------------------- brisk walk: same IK, faster and longer striding
WALK_GAIT = dict(WALK_N=WALK_N, CYCLE=CYCLE, DUTY=DUTY, HEEL_PH=HEEL_PH, TOE_PH=TOE_PH, HEEL_UP=HEEL_UP, TOE_DOWN=TOE_DOWN, LIFT=LIFT,
                 BOB0=BOB0, BOBA=BOBA, LIVE=LIVE, ARM=ARM, ELBOW=ELBOW, LEAN=LEAN, STRIDE=STRIDE, SPEED=SPEED)
BRISK_TARGET = 1.70
BRISK_N = 21                                        # 20 intervals = 0.833 s per two steps (144 steps a minute)
globals().update(WALK_N=BRISK_N, CYCLE=(BRISK_N - 1) / FPS, DUTY=0.56, HEEL_PH=0.13, TOE_PH=0.62, HEEL_UP=18.0, TOE_DOWN=38.0,
                 LIFT=0.095, BOBA=0.018, LIVE=1.4, ARM=1.35, ELBOW=22.0, LEAN=6.0)
_want = BRISK_TARGET * CYCLE
BOB0 = -0.040
while stride_fits(_want) > 0.99 and BOB0 > -0.11: BOB0 -= 0.005
STRIDE = _want
while stride_fits(STRIDE) > 0.99 and STRIDE > 0.8: STRIDE -= 0.01
SPEED = STRIDE / CYCLE
make_action("walk_brisk", BRISK_N, walk)
make_action("walk_brisk_carry", BRISK_N, walk_carry)
